<template>
	<Layout>
		<div class="container box_general">
			<div class="header_box">
				<h2><i class="icon-medicine"></i>Vademecum</h2>
			</div>

			<div class="filters-box">
				<div class="filter">
					<label>BUSCAR</label>
					<div class="filter-input">
						<i class="icon icon-search"></i>
						<input type="text" class="form-control" placeholder="Buscar" v-model="filters.search" @keyup.enter="updateFilters($event)" />
						<div
							class="btn btn-light btn-clear-filter"
							v-if="filters.search"
							@click="
								filters.search = null
								updateFilters()
							"
						>
							<i class="icon icon-close"></i>
						</div>
					</div>
				</div>
			</div>

			<table class="table table-clickeable">
				<tr class="table-head">
					<td>Vademecum</td>
					<td>Archivo</td>
					<td></td>
				</tr>

				<tr v-for="item of list" :key="item.id">
					<td>
						<div class="tc">
							<span>{{ item.name }}</span>
						</div>
					</td>
					<td>
						<div class="tc">
							<span>{{ item.fileUrl }} </span>
						</div>
					</td>
					<td class="text-right">
						<a :href="item.downloadURL" target="_blank" class="btn btn-light">
							<i class="fa fa-download"></i>
						</a>
					</td>
				</tr>
			</table>

			<div class="alert alert-info text-center" v-if="list.length == 0">No se han encontrado archivos</div>

			<Pagination :pageData="pagination" @pageChange="pageChange" />
		</div>
	</Layout>
</template>

<script>
import gql from "graphql-tag"

export default {
	name: "Vademecum",

	data() {
		return {
			list: [],
			loading: true
		}
	},
	beforeMount() {
		this.filters = this.getValidUrlParams()
		this.load()
	},

	methods: {
		load() {
			this.loading = true
			this.$apollo
				.query({
					query: gql`
						query($take: Int, $skip: Int, $search: String) {
							vademecums(take: $take, skip: $skip, search: $search) {
								data {
									id
									name
									fileUrl
									downloadURL
								}
								pageInfo {
									totalItems
								}
							}
						}
					`,
					variables: {
						take: this.pagination.length,
						skip: this.pagination.skip,
						search: this.filters.search
					},
					fetchPolicy: "no-cache"
				})
				.then(data => {
					this.list = data.data.vademecums.data.map(item => {
						return { ...item, loading: false }
					})
					this.pagination.pageInfo = data.data.vademecums.pageInfo
					this.loading = false
				})
		}
	}
}
</script>

